Widget _buildSalesReportsSection() {
  return Consumer2<ProductProvider, OrderProvider>(
    builder: (context, productProvider, orderProvider, child) {
      final orders = orderProvider.orders;
      final products = productProvider.products;

      double totalSales = 0.0;
      int completedSalesCount = 0;
      int totalProductsSold = 0;
      Map<String, double> productRevenue = {};
      Map<String, int> productQtySold = {};

      final now = DateTime.now();
      double currentMonthSales = 0.0;
      double previousMonthSales = 0.0;

      for (var order in orders) {
        if (order.status.toLowerCase() != 'cancelled' && order.status.toLowerCase() != 'pending') {
          totalSales += order.totalAmount;
          completedSalesCount++;

          if (order.timestamp.year == now.year && order.timestamp.month == now.month) {
            currentMonthSales += order.totalAmount;
          } else if (order.timestamp.year == (now.month == 1 ? now.year - 1 : now.year) &&
                     order.timestamp.month == (now.month == 1 ? 12 : now.month - 1)) {
            previousMonthSales += order.totalAmount;
          }

          for (var item in order.items) {
            totalProductsSold += item.qty;
            productRevenue[item.productId] = (productRevenue[item.productId] ?? 0.0) + item.subtotal;
            productQtySold[item.productId] = (productQtySold[item.productId] ?? 0) + item.qty;
          }
        }
      }

      double salesGrowth = previousMonthSales > 0 ? ((currentMonthSales - previousMonthSales) / previousMonthSales) * 100 : (currentMonthSales > 0 ? 100.0 : 0.0);

      return Padding(
        padding: const EdgeInsets.only(bottom: 32.0, left: 8.0, right: 8.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text('Sales Intelligence', style: TextStyle(fontSize: 28, fontWeight: FontWeight.bold, color: Colors.black87, letterSpacing: -0.5)),
            const SizedBox(height: 8),
            Text('Interactive dashboard for revenue and product performance.', style: TextStyle(fontSize: 15, color: Colors.grey.shade600)),
            const SizedBox(height: 32),

            _buildCreativeSalesSummary(totalSales, completedSalesCount, totalProductsSold, salesGrowth),
            const SizedBox(height: 32),

            LayoutBuilder(
              builder: (context, constraints) {
                bool isDesktop = constraints.maxWidth >= 900;
                if (isDesktop) {
                  return Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Expanded(flex: 3, child: _buildCreativeSalesTrend(orders, currentMonthSales)),
                      const SizedBox(width: 24),
                      Expanded(flex: 2, child: _buildCreativeTopProducts(products, productRevenue, productQtySold)),
                    ],
                  );
                } else {
                  return Column(
                    children: [
                      _buildCreativeSalesTrend(orders, currentMonthSales),
                      const SizedBox(height: 24),
                      _buildCreativeTopProducts(products, productRevenue, productQtySold),
                    ],
                  );
                }
              },
            ),
          ],
        ),
      );
    },
  );
}

